\label{lem:slice}
For every $h:F^d\to\mathbb C$,
\begin{equation}\label{eq:slice}
\|h*K\|_{L^4(F^d)}\lesssim q^{(d-1)/2}\sum_{z\in F}\big\|(\widetilde h_zd\sigma)^\vee\big\|_{L^4(F^d)}.
\end{equation}

\label{lem:eps-removal}
Let $s_0>1$, and suppose that for every $\varepsilon>0$,
\begin{equation}\label{eq:restricted}
\|\widehat g\|_{L^2(P,d\sigma)}\lesssim_\varepsilon q^{\varepsilon}|G|^{1/s_0}
\end{equation}
holds for every $g$ with $g\sim1$ on its support $G$. Then
\begin{equation}\label{eq:strong-type}
\|\widehat g\|_{L^2(P,d\sigma)}\lesssim_s\|g\|_{L^s(F^d)}\qquad\text{for every }1\le s<s_0.
\end{equation}

\label{lem:rect}
Suppose that $-1$ is not a square in $F$. Then, for every $A\subset F^2$,
\begin{equation}\label{eq:rect-CS}
\mathcal R(A)\lesssim|A|^{5/2},
\end{equation}
and
\begin{equation}\label{eq:rect-vinh}
\mathcal R(A)\lesssim q^{-1}|A|^{3}+q^{1/2}|A|^{2},
\end{equation}
the second bound being the smaller for $q\le|A|\le q^2$.

\label{lem:rect-prime}
Suppose that $F=\mathbb F_p$, that $-1$ is not a square in $F$, and that $|A|\le p^{26/21}$. Then, for every $\varepsilon>0$
\begin{equation}\label{eq:rect-prime}
\mathcal R(A)\lesssim_\varepsilon|A|^{99/41+\varepsilon}.
\end{equation}

\label{lem:regular}
Every $A\subset F^2$ is a disjoint union of $O(\log q)$ regular sets, with possibly repeated regularity parameters, together with at most one irregular set. If $A$ and $B$ are $k$-regular with $|A|\sim|B|\sim m$, or both irregular with $k\sim m^{1/2}$, then
\begin{equation}\label{eq:reg-T}
\mathcal T(A,B)\lesssim m^3k+m^4k^{-2}.
\end{equation}
If, in addition, $-1$ is not a square in $F$, then
\begin{equation}\label{eq:reg-R}
\mathcal R(A)\lesssim m^2k.
\end{equation}

\label{prop:bilinear-ineq}
With the notation above,
\begin{equation}\label{eq:BiMT}
\|\widehat g\|_{L^2(P,d\sigma)}\lesssim|G|^{1/2}+|G|^{3/8}\Big(\sum_{z}\|g_z*K\|_4^2+\sum_{z\ne z'}\|g_z*K\,g_{z'}*K\|_2\Big)^{1/4},
\end{equation}
the linear term satisfies
\begin{equation}\label{eq:linear}
\|g_z*K\|_4^4\lesssim q^{-1}\mathcal R(G_z),
\end{equation}
and the bilinear term satisfies
\begin{equation}\label{eq:bilinear}
\|g_z*K\,g_{z'}*K\|_2^2\lesssim q^{-1}|G_z||G_{z'}|+q^{-2}\mathcal T(G_z,G_{z'})\qquad(z\ne z').
\end{equation}

\label{prop:general-B}
Suppose that $-1$ is not a square in $F$. Let $A,B\subset F^2$ be $k$-regular sets, or both irregular sets, with $|A|\sim|B|\sim m$. Then
\begin{equation}\label{eq:general-B}
\mathcal B(A,B)\lesssim m^{8/3}q^{2/3}+m^{7/2}.
\end{equation}

\label{lem:LPV}
Let $A\subset\mathbb F_p^2$ with $|A|=m$ and let $\mathcal L$ be a family of $L$ lines spanning $t$ directions, with $t\le c_0p^2/m$ for a sufficiently small absolute constant $c_0>0$. Then
\begin{equation}\label{eq:LPV}
I(A,\mathcal L)\lesssim t^{2/9}L^{5/9}m^{7/9}+t^{1/2}L^{1/2}m^{1/2}+L^{2/3}m^{2/3}+L+m.
\end{equation}

\label{lem:vinh}
For every $A\subset\mathbb F_p^2$ with $|A|=m$ and every family $\mathcal L$ of $L$ lines,
\begin{equation}\label{eq:vinh-inc}
I(A,\mathcal L)\lesssim \frac{mL}{p}+(pmL)^{1/2}.
\end{equation}

\label{lem:directional-energy}
Let $A\subset\mathbb F_p^2$ with $|A|=m$, and let $\mathcal L$ be a family of lines each meeting $A$ in at most $C m^{1/2}$ points, where $C$ is a fixed absolute constant. Then for every $\varepsilon>0$,
\begin{equation}\label{eq:dir-energy}
\sum_\theta E_{\theta,\mathcal L}(A)^2\lesssim_\varepsilon p^\varepsilon\Big(m^3\min(m,p)^{1/3}+\frac{m^4}{p}+pm^2\Big).
\end{equation}

\label{prop:prime-B}
Suppose that $-1$ is not a square in $\mathbb F_p$. Let $A,B\subset\mathbb F_p^2$ be $k$-regular sets, or both irregular sets, with $|A|\sim|B|\sim m$. Then, for every $\varepsilon>0$,
\begin{equation}\label{eq:prime-B}
\mathcal B(A,B)\lesssim_\varepsilon p^\varepsilon\Big(m^{8/3}p^{2/3}+m^3\min(m,p)^{1/3}+\frac{m^4}{p}+pm^2\Big).
\end{equation}

\label{lem:hybrid-rectangle}
Suppose that $-1$ is not a square in $\mathbb F_p$, and let $A\subset\mathbb F_p^2$ have cardinality $n$ with
\[
n\lesssim p^{10/7}.
\]
Then, for every $\varepsilon>0$,
\begin{equation}\label{eq:hybrid-rectangle}
\mathcal R(A)\lesssim_\varepsilon p^\varepsilon n^2p^{3/7}.
\end{equation}

We first dispose of degenerate rectangles.  If one of the four edge differences is zero, say $x_0=x_1$, then the two remaining corner conditions involving the opposite edge give $(x_3-x_2)\cdot(x_3-x_2)=0$.  Since $-1$ is not a square, the form $u\cdot u$ has no nonzero zeros, and hence $x_2=x_3$.  Thus degenerate rectangles are determined by two points of $A$, up to cyclic relabeling, and contribute $O(n^2)$, which is absorbed by the right side of \eqref{eq:hybrid-rectangle}. We may therefore count only rectangles whose edge-lines are genuine lines.

For a dyadic integer $k\ge2$, let $\mathcal L_k$ denote the lines containing between $k$ and $2k$ points of $A$.  The Stevens--de Zeeuw incidence theorem gives
\begin{equation}\label{eq:rich-SdZ}
|\mathcal L_k|\lesssim n^{11/4}k^{-15/4}+nk^{-1}+n^{13/2}p^{-15/2}.
\end{equation}
On the other hand, Vinh's estimate gives, whenever $k\gtrsim n/p$,
\begin{equation}\label{eq:rich-vinh}
|\mathcal L_k|\lesssim pnk^{-2}.
\end{equation}

We use the standard dyadic rectangle count from the proof of Lemma \ref{lem:rect-prime}.  Assign to each rectangle one of its edge-lines having maximal intersection with $A$.  If $K\ge1$, the rectangles assigned to lines containing at most $K$ points contribute
\begin{equation}\label{eq:rect-low-rich}
\lesssim n^2K.
\end{equation}
For a dyadic class $k\ge K$, the contribution is at most
\begin{equation}\label{eq:rect-rich-classes}
\begin{cases}
k^3|\mathcal L_k|,&K\le k\le n^{1/2},\\
nk|\mathcal L_k|,&k\ge n^{1/2}.
\end{cases}
\end{equation}
Indeed, the first line follows by choosing an assigned edge, one endpoint, and the adjacent perpendicular edge.  For the second line, the perpendicular lines through the points of a fixed edge are parallel and disjoint, so their intersections with $A$ have total size at most $n$.

Take a dyadic $K\sim C_0p^{3/7}$, where $C_0$ is a sufficiently large absolute constant. Since $n\lesssim p^{10/7}$, we may choose $C_0$ so that $K\gtrsim n/p$. If $K\ge n$, then \eqref{eq:rect-low-rich} already proves the result, so assume $K<n$. First suppose that $n\ge p^{8/7}$.  Applying \eqref{eq:rich-vinh} in \eqref{eq:rect-rich-classes}, both richness ranges contribute at most
\[
pn^{3/2}\le n^2p^{3/7}
\]
per dyadic class.  Together with \eqref{eq:rect-low-rich}, and after summing the $O(\log p)$ dyadic classes, this proves the claim in this case.

It remains to consider $n\le p^{8/7}$.  For $K\le k\le n^{1/2}$, combine \eqref{eq:rich-SdZ} and \eqref{eq:rich-vinh}. We use the elementary inequality
\[
\min\{U+V,W\}\le \min\{U,W\}+V
\qquad (U,V,W\ge0)
\]
to separate the leading term in \eqref{eq:rich-SdZ} from its two error terms. The leading terms satisfy
\[
\begin{aligned}
\min\{n^{11/4}k^{-3/4},\,pnk\}
&\le
\big(n^{11/4}k^{-3/4}\big)^{4/7}(pnk)^{3/7}\\
&=n^2p^{3/7}.
\end{aligned}
\]
The other two terms from \eqref{eq:rich-SdZ}, after multiplication by $k^3$, are bounded by
\[
nk^2+n^{13/2}p^{-15/2}k^3
\le n^2+n^8p^{-15/2}
\lesssim n^2p^{3/7},
\]
where the last inequality uses $n\le p^{8/7}$.  For $k\ge n^{1/2}$, \eqref{eq:rich-SdZ} and the second line of \eqref{eq:rect-rich-classes} give
\[
\begin{aligned}
n^{15/4}k^{-11/4}+n^2+n^{15/2}p^{-15/2}k
&\le n^{19/8}+n^2+n^{17/2}p^{-15/2}\\
&\lesssim n^2p^{3/7},
\end{aligned}
\]
where we used $k\le n$ and $n\le p^{8/7}$.  Summing the $O(\log p)$ dyadic classes and absorbing the logarithm into $p^\varepsilon$ proves \eqref{eq:hybrid-rectangle}.

\label{prop:six-bilinear}
Let $A,B\subset F^6$ and let $|f|\le1_A$, $|h|\le1_B$. Then
\begin{equation}\label{eq:six-bilinear-one-sided}
|\mathcal Q(f,h)|\lesssim|A\cap B|+q^{-1}|A|^{3/4}|B|^{3/4}+|A|^{3/4}|B|^{1/2},
\end{equation}
and consequently
\begin{equation}\label{eq:six-bilinear-symmetric}
|\mathcal Q(f,h)|\lesssim|A\cap B|+q^{-1}|A|^{3/4}|B|^{3/4}+\min\{|A|^{3/4}|B|^{1/2},|A|^{1/2}|B|^{3/4}\}.
\end{equation}
We also have the (cruder) estimate
\begin{equation}\label{eq:six-parseval}
|\mathcal Q(f,h)|\lesssim q|A|^{1/2}|B|^{1/2}.
\end{equation}

Since $(d\sigma)^\vee=\delta_0+K$, the contribution of $\delta_0$ to $\mathcal Q(f,h)=\langle f,h*(d\sigma)^\vee\rangle$ is $\langle f,h\rangle$, of modulus at most $|A\cap B|$. For the contribution of $K$, H\"older's inequality with exponents $\tfrac43$ and $4$ gives
\begin{equation}\label{eq:six-holder}
|\langle f,h*K\rangle|\le\|f\|_{4/3}\,\|h*K\|_4\le|A|^{3/4}\,\|h*K\|_4.
\end{equation}
To estimate $\|h*K\|_4$ we use the slice estimate of Lemma \ref{lem:slice} with $d=6$. For $z\in F$ let $h_z(\eta)=h(\eta,z)$ for $\eta\in F^5$, supported on $B_z=\{\eta\in F^5:(\eta,z)\in B\}$, and let $\widetilde h_z$ be its lift to the paraboloid, defined by $\widetilde h_z(\eta,\eta\cdot\eta)=h_z(\eta)$ on its support
\[
\widetilde B_z=\{(\eta,\eta\cdot\eta):\eta\in B_z\}\subset P,
\]
so that $|\widetilde B_z|=|B_z|$ and $\sum_z|B_z|=|B|$. Lemma \ref{lem:slice} gives
\begin{equation}\label{eq:six-slice}
\|h*K\|_4\lesssim q^{5/2}\sum_z\big\|(\widetilde h_zd\sigma)^\vee\big\|_4.
\end{equation}
For any function $\phi:P\to\mathbb C$ with $|\phi|\le1_E$ for some set $E\subset P$, expanding the fourth power and using Plancherel on $F^6$ identifies $\|(\phi d\sigma)^\vee\|_4^4$ with a normalized weighted count of additive quadruples in $E$, the quadruple $(\xi_1,\xi_2,\xi_3,\xi_4)$ with $\xi_1+\xi_2=\xi_3+\xi_4$ carrying the weight $\phi(\xi_1)\phi(\xi_2)\overline{\phi(\xi_3)\phi(\xi_4)}$. Since $|\phi|\le1_E$, each weight has modulus at most $1$, so this is at most the unweighted additive energy $\Lambda(E)$, whence
\begin{equation}\label{eq:six-L4}
\big\|(\phi d\sigma)^\vee\big\|_4\le q^{-7/2}\Lambda(E)^{1/4}.
\end{equation}
Applying the energy estimate \eqref{eq:six-energy} to $E=\widetilde B_z$ and $\phi=\widetilde h_z$ gives $\Lambda(\widetilde B_z)^{1/4}\lesssim q^{-1/4}|B_z|^{3/4}+q^{1/2}|B_z|^{1/2}$, so combining \eqref{eq:six-slice} and \eqref{eq:six-L4},
\begin{equation}\label{eq:six-hK}
\|h*K\|_4\lesssim q^{-1}\sum_z\Lambda(\widetilde B_z)^{1/4}\lesssim q^{-5/4}\sum_z|B_z|^{3/4}+q^{-1/2}\sum_z|B_z|^{1/2}.
\end{equation}
There are at most $q$ nonempty slices, so H\"older's inequality gives $\sum_z|B_z|^{3/4}\le q^{1/4}|B|^{3/4}$ and $\sum_z|B_z|^{1/2}\le q^{1/2}|B|^{1/2}$, and the right side of \eqref{eq:six-hK} reduces to
\begin{equation}\label{eq:six-hK2}
\|h*K\|_4\lesssim q^{-1}|B|^{3/4}+|B|^{1/2}.
\end{equation}
Substituting \eqref{eq:six-hK2} into \eqref{eq:six-holder} gives \eqref{eq:six-bilinear-one-sided}, and interchanging the roles of $f$ and $h$ and keeping the smaller of the two bounds gives \eqref{eq:six-bilinear-symmetric}. Finally, by Plancherel on $F^6$,
\[
\|\widehat f\|_{L^2(P,d\sigma)}^2=q^{-5}\sum_{\xi\in P}|\widehat f(\xi)|^2\le q^{-5}\sum_{\xi\in F^6}|\widehat f(\xi)|^2=q\|f\|_2^2,
\]
so the Cauchy--Schwarz inequality $|\mathcal Q(f,h)|\le\|\widehat f\|_{L^2(P,d\sigma)}\|\widehat h\|_{L^2(P,d\sigma)}$ gives \eqref{eq:six-parseval}.
